-- ----------------------------
-- Table structure for equipment
-- ----------------------------
DROP TABLE IF EXISTS `equipment`;
CREATE TABLE `equipment` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `uuid` varchar(64) CHARACTER SET latin1 COLLATE latin1_swedish_ci DEFAULT NULL,
  `device_uid` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT '' COMMENT '设备唯一ID 不可修改',
  `channel_id` varchar(200) CHARACTER SET latin1 COLLATE latin1_swedish_ci DEFAULT NULL COMMENT '设备的通道id',
  `device_code` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT '' COMMENT '设备编码 可修改',
  `sys_admin_id` bigint DEFAULT NULL COMMENT '用户id',
  `group_id` bigint unsigned DEFAULT NULL COMMENT '设备分组的id',
  `type` tinyint DEFAULT '0' COMMENT '类型0全部 1R版本 2V版 3E粉',
  `state` tinyint DEFAULT NULL COMMENT '状态 1 在线 0离线',
  `sys_admin_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '邀请码',
  `last_time` datetime DEFAULT NULL COMMENT '最近在线时间',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` tinyint DEFAULT '0' COMMENT '删除标志',
  `creator` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT '' COMMENT '添加人',
  `updator` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT '' COMMENT '更新人',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `device_uid` (`device_uid`) USING BTREE,
  KEY `group_id` (`group_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=326 DEFAULT CHARSET=latin1 ROW_FORMAT=COMPACT COMMENT='设备信息表';

-- ----------------------------
-- Records of equipment
-- ----------------------------
BEGIN;
COMMIT;

