-- ----------------------------
-- Table structure for live_hot_sub_task
-- ----------------------------
DROP TABLE IF EXISTS `live_hot_sub_task`;
CREATE TABLE `live_hot_sub_task` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `uuid` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'uuid',
  `task_detail_id` bigint DEFAULT NULL COMMENT '任务详情Id',
  `task_type` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT '' COMMENT '任务类型 live_chart:实时互动 live_hot:超级热度',
  `device_uid` varchar(200) CHARACTER SET latin1 COLLATE latin1_swedish_ci DEFAULT NULL COMMENT '设备唯一Id 对应equipment表中的device_uid',
  `state` tinyint DEFAULT NULL COMMENT '状态 0不在任务中1任务中',
  `gift_page` int DEFAULT '0' COMMENT '礼物页数',
  `gift_number` int DEFAULT '0' COMMENT '礼物数量',
  `gift_box` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '礼物格子数 ( no1 ......)',
  `red_envelope_time` int DEFAULT '0' COMMENT '抢红包时间',
  `give_light` int DEFAULT '0' COMMENT '0表示不赠送1表示赠送',
  `make_list_number` int DEFAULT '0' COMMENT '打榜关注数量',
  `click_number` int DEFAULT '0' COMMENT '点击次数',
  `content` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '私信文本内容',
  `remarks` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '备注',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `send_state` tinyint DEFAULT '0' COMMENT '任务发送状态 0未发送 1已发送',
  `send_took_millis` int DEFAULT NULL COMMENT '任务发送耗时(毫秒)',
  `send_time` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '任务发送时间',
  `del_flag` int DEFAULT NULL COMMENT '删除标志',
  `task_expect_running` int DEFAULT '0' COMMENT '任务时间',
  `comment_interval` int DEFAULT NULL COMMENT '评论最大间隔',
  `creator` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '创建人',
  `updator` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '更新人',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=1826 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=COMPACT COMMENT='超级热度子任务表';

-- ----------------------------
-- Records of live_hot_sub_task
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for sys_admin
-- ----------------------------
DROP TABLE IF EXISTS `sys_admin`;
CREATE TABLE `sys_admin` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键',
  `uuid` varchar(32) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT 'uuid',
  `username` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '用户名(用于登录使用，一般使用简称)',
  `fullname` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '全称，一般填写公司名称',
  `avatar_url` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '头像',
  `sex` tinyint DEFAULT '3' COMMENT '1,男:male;2,女:female;3,保密:secret',
  `pwd` varchar(500) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '密码',
  `salt` varchar(500) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '密钥',
  `state` tinyint DEFAULT '1' COMMENT '0,停用:disable;1,启用:enable',
  `role_ids` varchar(5000) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '角色ID集合',
  `type` tinyint DEFAULT '1' COMMENT '类型:1管理员;2代理商;3商家;',
  `user_id` int DEFAULT NULL COMMENT '对应前台的用户ID',
  `shop_id` int DEFAULT NULL COMMENT '商家id',
  `agent_id` int DEFAULT NULL COMMENT '代理商id',
  `parent_id` int DEFAULT NULL COMMENT '父级ID',
  `code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '邀请码',
  `ports` int DEFAULT '0' COMMENT '代理商最多设备数量',
  `login_time` datetime DEFAULT NULL COMMENT '登陆时间',
  `sort` bigint DEFAULT NULL COMMENT '排序号',
  `err_count` tinyint DEFAULT '0' COMMENT '密码连续错误次数',
  `stop_date` datetime DEFAULT NULL COMMENT '停用时间',
  `mobile` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '手机号码',
  `right_json` varchar(1000) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '总操作权限的json串',
  `del_flag` tinyint DEFAULT '0' COMMENT '0正常,1删除',
  `version` int DEFAULT '0' COMMENT '版本号',
  `creator` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '创建人',
  `updator` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '更新人',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `username` (`username`) USING BTREE,
  KEY `del_flag` (`del_flag`) USING BTREE,
  KEY `userId` (`user_id`) USING BTREE,
  KEY `parentId` (`parent_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=246 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_bin ROW_FORMAT=COMPACT COMMENT='系统用户表';

-- ----------------------------
-- Records of sys_admin
-- ----------------------------
BEGIN;
COMMIT;

