CREATE TABLE `sys_admin_login_log` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键',
  `uuid` varchar(32) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL,
  `username` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '登录用户名',
  `admin_id` varchar(32) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '后台用户ID',
  `pwd` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '登录的密码',
  `state` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT '1' COMMENT '登录状态 成功 失败',
  `login_ip` varchar(15) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT '1' COMMENT '登录ip',
  `del_flag` tinyint DEFAULT '0' COMMENT '0正常,1删除',
  `version` int DEFAULT '0' COMMENT '版本',
  `creator` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '创建人',
  `updator` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '更新人',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `username` (`username`) USING BTREE,
  KEY `parentId` (`admin_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_bin ROW_FORMAT=COMPACT COMMENT='系统用户登录日志';

-- ----------------------------
-- Table structure for sys_admin_port
-- ----------------------------
DROP TABLE IF EXISTS `sys_admin_port`;
CREATE TABLE `sys_admin_port` (
  `id` int NOT NULL AUTO_INCREMENT,
  `operat_admin` int DEFAULT NULL COMMENT '操作者的用户id',
  `sys_admin_id` int DEFAULT NULL COMMENT '代理商用户表的id',
  `start_port` int DEFAULT NULL COMMENT '开始的端口数量',
  `update_port` int DEFAULT NULL COMMENT '更新后端口数量',
  `create_time` datetime DEFAULT NULL COMMENT ' 创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `uuid` int DEFAULT NULL COMMENT 'uuid ',
  `del_flag` int DEFAULT NULL COMMENT '删除标记',
  `creator` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '作者',
  `updator` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '更新者',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=21 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=COMPACT;

-- ----------------------------
-- Records of sys_admin_port
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for sys_bank
-- ----------------------------
DROP TABLE IF EXISTS `sys_bank`;
CREATE TABLE `sys_bank` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'id',
  `uuid` varchar(32) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL,
  `sort` tinyint DEFAULT NULL COMMENT '排序',
  `name` varchar(256) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '银行名称',
  `code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '内部编码-唯一的不会变的。',
  `state` tinyint DEFAULT '0' COMMENT '0,显示:display;1,隐藏:hide',
  `icon` varchar(512) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '图标保存地址',
  `del_flag` tinyint DEFAULT '0' COMMENT '0正常,1删除',
  `version` int DEFAULT '0' COMMENT '版本',
  `creator` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '添加人',
  `updator` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '更新人',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `inCode` (`code`) USING BTREE,
  KEY `del_flag` (`del_flag`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=48 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_bin ROW_FORMAT=COMPACT COMMENT='系统配置的银行列表';

-- ----------------------------
-- Records of sys_bank
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for sys_banner
-- ----------------------------
DROP TABLE IF EXISTS `sys_banner`;
CREATE TABLE `sys_banner` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键',
  `uuid` varchar(32) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT 'uuid',
  `version` int DEFAULT '0' COMMENT '版本号',
  `title` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '标题',
  `pic_url` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '图片url',
  `link_url` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '跳转链接',
  `sort` int DEFAULT NULL COMMENT '排序',
  `is_show` int DEFAULT '0' COMMENT '是否显示1：是 0：否',
  `type` int DEFAULT NULL COMMENT '类型 1.普通   2.树木',
  `del_flag` tinyint DEFAULT '0' COMMENT '删除标记  0:否 1:是',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `creator` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '添加人 system:系统 user,xxx:系统用户,用户id',
  `updator` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '更新人  system:系统 user,xxx:系统用户,用户id',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=38 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_bin ROW_FORMAT=COMPACT COMMENT='首页轮播图';

-- ----------------------------
-- Records of sys_banner
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for sys_conf
-- ----------------------------
DROP TABLE IF EXISTS `sys_conf`;
CREATE TABLE `sys_conf` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键',
  `uuid` int DEFAULT NULL COMMENT 'uuid',
  `name` varchar(30) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT '' COMMENT '名称',
  `nid` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT '' COMMENT '标识',
  `value` varchar(128) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT '' COMMENT '名称对应的值',
  `type` tinyint DEFAULT '1' COMMENT '1,系统底层配置:systemConfig;2,各种费率配置:feeConfig;3,邮件/短信配置信息:smsConfig;4,附加增值功能配置信息:additionConfig;5,第三方资金托管相关的配置:thirdConfig ',
  `state` tinyint DEFAULT '1' COMMENT '0,禁用:forbiden  1,启用:enable',
  `remark` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '备注',
  `del_flag` tinyint DEFAULT '0' COMMENT '0正常,1删除',
  `version` int DEFAULT '0' COMMENT '版本',
  `creator` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '添加人',
  `updator` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '更新人',
  `create_time` datetime DEFAULT NULL COMMENT '更新时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `nid` (`nid`) USING BTREE,
  KEY `del_flag` (`del_flag`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=160 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_bin ROW_FORMAT=COMPACT COMMENT='系统参数表';

-- ----------------------------
-- Records of sys_conf
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for sys_dict
-- ----------------------------
DROP TABLE IF EXISTS `sys_dict`;
CREATE TABLE `sys_dict` (
  `id` varchar(32) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL COMMENT '主键',
  `uuid` varchar(32) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL,
  `nid` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '标识',
  `name` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '名称',
  `state` tinyint DEFAULT '1' COMMENT '0,停用:disable;1,启用:enable ',
  `val` varchar(500) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '值',
  `sort` int DEFAULT '0' COMMENT '排序',
  `desc` varchar(500) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '描述',
  `del_flag` tinyint DEFAULT '0' COMMENT '0正常,1删除',
  `version` int DEFAULT '0' COMMENT '版本',
  `creator` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '添加人',
  `updator` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '更新人',
  `create_time` datetime DEFAULT NULL COMMENT '更新时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `nid` (`nid`) USING BTREE,
  KEY `del_flag` (`del_flag`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_bin ROW_FORMAT=COMPACT COMMENT='字典表 -- 公共表';

-- ----------------------------
-- Table structure for sys_help
-- ----------------------------
DROP TABLE IF EXISTS `sys_help`;
CREATE TABLE `sys_help` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `uuid` varchar(32) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT 'uuid',
  `version` int DEFAULT NULL COMMENT '版本号',
  `sort` int DEFAULT NULL COMMENT '排序',
  `title` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '标题',
