-- ----------------------------
-- Table structure for sys_log_template
-- ----------------------------
DROP TABLE IF EXISTS `sys_log_template`;
CREATE TABLE `sys_log_template` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键',
  `uuid` varchar(32) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT 'uuid',
  `type` tinyint DEFAULT NULL COMMENT '1,资金日志:accountLog;2,会员日志:memberLog',
  `value` varchar(1024) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '模板信息',
  `name` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '名称',
  `remark` varchar(500) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '模板备注',
  `nid` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '模板标识',
  `pay_type` tinyint DEFAULT '0' COMMENT '0,不变:unchanged;1,收入:income;2,支出:expend;3,充值:recharge;4,提现:mention',
  `del_flag` tinyint DEFAULT '0' COMMENT '0正常,1删除',
  `version` int DEFAULT '0' COMMENT '版本',
  `creator` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '添加人',
  `updator` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '更新人',
  `create_time` datetime DEFAULT NULL COMMENT '更新时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `nid` (`nid`) USING BTREE,
  KEY `del_flag` (`del_flag`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=136 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_bin ROW_FORMAT=COMPACT COMMENT='用户操作日志模板表';

-- ----------------------------
-- Records of sys_log_template
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for sys_menu
-- ----------------------------
DROP TABLE IF EXISTS `sys_menu`;
CREATE TABLE `sys_menu` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键',
  `uuid` int DEFAULT NULL COMMENT 'uuid',
  `parent_id` int DEFAULT NULL COMMENT '父级菜单ID',
  `parent_name` varchar(32) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '父级菜单名称',
  `name` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '菜单名称',
  `url` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '访问URL',
  `type` tinyint DEFAULT NULL COMMENT '0,菜单:menu;1,操作:opt',
  `level` tinyint DEFAULT '1' COMMENT '0,顶级菜单:topMenu;1,1级菜单:firstMenu;2,二级菜单:secondMenu;3,三级菜单:thirdMenu',
  `images` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '图标',
  `sort` int DEFAULT NULL COMMENT '排序号',
  `right_val` int DEFAULT '0' COMMENT '权限值',
  `right_pos` int DEFAULT '0' COMMENT '权限位',
  `description` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '菜单描述',
  `is_parent` tinyint DEFAULT '0' COMMENT '0,否:no;1,是:yes',
  `del_flag` tinyint DEFAULT '0' COMMENT '0正常,1删除',
  `version` int DEFAULT '0' COMMENT '版本',
  `creator` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '添加人',
  `updator` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '更新人',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `del_flag` (`del_flag`) USING BTREE,
  KEY `parent_menu_id` (`parent_id`) USING BTREE,
  KEY `type` (`type`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=345 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_bin ROW_FORMAT=COMPACT COMMENT='系统菜单表 -- 公共表';

-- ----------------------------
-- Records of sys_menu
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for sys_notice
-- ----------------------------
DROP TABLE IF EXISTS `sys_notice`;
CREATE TABLE `sys_notice` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `uuid` varchar(32) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT 'uuid',
  `version` int DEFAULT NULL COMMENT '版本号',
  `sort` int DEFAULT NULL COMMENT '排序',
  `title` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '标题',
  `content` text CHARACTER SET utf8mb3 COLLATE utf8mb3_bin COMMENT '内容',
  `publisher` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '发布人',
  `publish_time` datetime DEFAULT NULL COMMENT '发布时间',
  `status` int DEFAULT '1' COMMENT '发布状态：1未发布 ：2已发布',
  `del_flag` tinyint DEFAULT NULL COMMENT '删除标记  0:否 1:是',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `creator` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '创建人',
  `updator` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '更新人',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=83 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_bin ROW_FORMAT=COMPACT COMMENT='系统公告';

-- ----------------------------
-- Records of sys_notice
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for sys_notice_log
-- ----------------------------
DROP TABLE IF EXISTS `sys_notice_log`;
CREATE TABLE `sys_notice_log` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键',
  `uuid` varchar(32) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL,
  `nid` varchar(32) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '编号',
  `type` tinyint DEFAULT NULL COMMENT '1,邮件:email;2,短信:sms;3,站内信:inletter;',
  `sender_id` int DEFAULT NULL COMMENT '发送用户ID',
  `receiver_id` int DEFAULT NULL COMMENT '接收用户ID',
  `receiver_type` tinyint DEFAULT '1' COMMENT '用户类型: 1普通用户;2;3厂家;',
  `state` tinyint DEFAULT NULL COMMENT '0,发送失败:sendFailure;1,发送成功:sendSuccess;2,发送中:sending;3,未读:unread;4,已读:read;',
  `title` varchar(500) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '标题',
  `content` text CHARACTER SET utf8mb3 COLLATE utf8mb3_bin COMMENT '发送内容',
  `result` text CHARACTER SET utf8mb3 COLLATE utf8mb3_bin COMMENT '发送结果信息',
  `receive_address` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '接收地址  类型为短信或站内信时有值',
  `tx_type` tinyint DEFAULT '1' COMMENT '所属业务类型:1系统通知;2订单相关;3其他(拓展用)',
  `tx_id` int DEFAULT NULL COMMENT '业务表id;比如业务类型是订单相关可能要在消息里展示订单信息,就要用到这个字段;',
  `del_flag` tinyint DEFAULT '0' COMMENT '0正常,1删除',
  `version` int DEFAULT '0' COMMENT '版本',
  `creator` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '添加人',
  `updator` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '更新人',
  `create_time` datetime DEFAULT NULL COMMENT '发送时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `receiver` (`receiver_id`) USING BTREE,
  KEY `del_flag` (`del_flag`) USING BTREE,
  KEY `createTime` (`create_time`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=5269 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_bin ROW_FORMAT=COMPACT COMMENT='通知记录表';

-- ----------------------------
-- Records of sys_notice_log
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for sys_notice_template
-- ----------------------------
DROP TABLE IF EXISTS `sys_notice_template`;
CREATE TABLE `sys_notice_template` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键',
  `uuid` varchar(32) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT 'uuid',
  `nid` varchar(30) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '编码，与notice_type组合起来唯一',
  `notice_type` tinyint DEFAULT NULL COMMENT '1,邮件:email;2,短信:sms;3,站内信:message;',
  `type` tinyint DEFAULT NULL COMMENT '1,系统通知:systemNotice;2,用户通知:userNotice;',
  `title` varchar(250) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '标题的freemarker模板',
  `template` varchar(1024) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '内容的freemarker模板',
  `template_remark` varchar(1024) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT 'remark的freemarker模板',
  `state` tinyint DEFAULT '2' COMMENT '0,禁用:forbidden;1,启用:enable',
  `remark` varchar(250) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '备注',
  `del_flag` tinyint DEFAULT '0' COMMENT '0正常,1删除',
  `version` int DEFAULT '0' COMMENT '版本',
  `creator` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '添加人',
  `updator` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '更新人',
  `create_time` datetime DEFAULT NULL COMMENT '添加时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=32 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_bin ROW_FORMAT=COMPACT COMMENT='通知类型模板表 -- 系统中对所有客户发送通知的模板';

-- ----------------------------
-- Records of sys_notice_template
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for sys_role
-- ----------------------------
DROP TABLE IF EXISTS `sys_role`;
CREATE TABLE `sys_role` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键',
  `uuid` varchar(32) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT 'uuid',
  `name` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '名称',
  `description` varchar(500) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '描述',
  `sort` tinyint DEFAULT '0' COMMENT '排序号',
  `menu_ids` varchar(5000) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '拥有的功能ID集合',
  `del_flag` tinyint NOT NULL DEFAULT '0' COMMENT '0正常,1删除',
  `version` int DEFAULT '0' COMMENT '版本',
  `creator` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '添加人',
  `updator` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '更新人',
  `create_time` datetime DEFAULT NULL COMMENT '更新时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `del_flag` (`del_flag`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=17 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_bin ROW_FORMAT=COMPACT COMMENT='系统角色表';

-- ----------------------------
-- Records of sys_role
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for sys_system_log
-- ----------------------------
DROP TABLE IF EXISTS `sys_system_log`;
CREATE TABLE `sys_system_log` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键',
  `uuid` varchar(32) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT 'uuid',
  `cause` int DEFAULT NULL COMMENT '0,没有权限:noRight;1,URL不存在:urlNotExists;2,未登录:noLogin;3,业务代码异常:exception',
  `cookie` varchar(1024) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT 'cookie数据',
  `desc` varchar(2000) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '描述',
  `ip` varchar(128) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '客户端ip',
  `method` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '访问方法',
  `referer` varchar(2000) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '源引用',
  `request_path` varchar(500) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '请求路径',
  `start_date` datetime DEFAULT NULL COMMENT '访问开始日期',
  `end_date` datetime DEFAULT NULL COMMENT '访问结束日期',
  `took` bigint DEFAULT NULL COMMENT '访问耗时',
  `status` tinyint DEFAULT NULL COMMENT '0,失败:failure;1,正常:normal;',
  `user_agent` varchar(1000) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '访问代理信息',
  `del_flag` tinyint DEFAULT '0' COMMENT '0正常,1删除',
  `version` int DEFAULT '0' COMMENT '版本',
  `creator` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '添加人 system:系统 user,xxx:系统用户,用户id',
  `updator` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '更新人  system:系统 user,xxx:系统用户,用户id',
  `create_time` datetime DEFAULT NULL COMMENT '更新时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=36104 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_bin ROW_FORMAT=COMPACT COMMENT='系统访问日志表 -- 记录每一次请求的详情';

-- ----------------------------
-- Records of sys_system_log
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for task
-- ----------------------------
DROP TABLE IF EXISTS `task`;
CREATE TABLE `task` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `comment_template_id` bigint DEFAULT NULL COMMENT '话术Id',
  `task_type` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT '' COMMENT '任务类型 live_hot超级热度 auto自动养号  live_chat 实时互动',
  `task_run_code` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT '' COMMENT '任务设置 now 立即执行 delay 定时任务',
  `task_name` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '任务名称',
  `task_content` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT '' COMMENT '任务内容 praise-点赞  concern-关注  comment-评论   turn-转发  look-查看主页',
  `task_start_time` datetime DEFAULT NULL COMMENT '开始执行时间 now的时候不填',
  `sys_admin_id` int DEFAULT NULL COMMENT '用户表的连接',
  `task_expect_running` int DEFAULT '0' COMMENT '任务运行时间',
  `task_end_time` datetime DEFAULT NULL COMMENT '任务结束时间',
  `live_in_Type` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT '' COMMENT '进入直播间方式',
  `live_in_content` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '直播文本',
  `analysis_content` varchar(255) CHARACTER SET latin1 COLLATE latin1_swedish_ci DEFAULT NULL COMMENT '解析的content地址',
  `comment_interval` int DEFAULT NULL COMMENT '评论最大间隔',
  `is_live_hot` int DEFAULT '0' COMMENT '0不属于超级热度和超级热度下的任务,1属于',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` int DEFAULT NULL COMMENT '删除标志',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=588 DEFAULT CHARSET=latin1 ROW_FORMAT=COMPACT;

-- ----------------------------
-- Records of task
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for task_details
-- ----------------------------
DROP TABLE IF EXISTS `task_details`;
CREATE TABLE `task_details` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `task_detail_uuid` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT '' COMMENT '任务详情的识别码',
  `task_id` bigint DEFAULT NULL COMMENT '任务Id',
  `task_type` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT '' COMMENT '任务类型 live_chart:实时互动 live_hot:超级热度',
  `device_uid` varchar(200) CHARACTER SET latin1 COLLATE latin1_swedish_ci DEFAULT NULL COMMENT '设备唯一Id 对应equipment表中的device_uid',
  `state` tinyint DEFAULT NULL COMMENT '状态 0不在任务中1任务中',
  `playtimes` int DEFAULT '0' COMMENT '播放次数',
  `fabulous` int DEFAULT '0' COMMENT '点赞次数',
  `homepages` int DEFAULT '0' COMMENT '查看主页次数',
  `forwards` int DEFAULT '0' COMMENT '转发次数',
  `follows` int DEFAULT '0' COMMENT '关注次数',
  `letters` int DEFAULT '0' COMMENT '私信次数',
  `comments` int DEFAULT '0' COMMENT '评论次数',
  `number` int DEFAULT '0' COMMENT '私信的个数',
  `letter_type` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '私信的方式 letterAdmin私信用户letterFans私信粉丝',
  `city` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '同城引流-城市名称',
  `apk_upgrade` int DEFAULT NULL COMMENT '设备更新类型 1 版本更新  2 设备更新',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `send_took_millis` int DEFAULT NULL COMMENT '任务发送耗时(毫秒)',
  `send_state` tinyint DEFAULT '0' COMMENT '任务发送状态 0未发送 1已发送',
  `send_time` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '任务发送时间',
  `remarks` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '备注',
  `del_flag` int DEFAULT NULL COMMENT '删除标志',
  `uuid` varchar(100) CHARACTER SET latin1 COLLATE latin1_swedish_ci DEFAULT NULL COMMENT 'uuid',
  `creator` varchar(20) CHARACTER SET latin1 COLLATE latin1_swedish_ci DEFAULT NULL COMMENT '作者',
  `updator` varchar(20) CHARACTER SET latin1 COLLATE latin1_swedish_ci DEFAULT NULL COMMENT '更新的作者',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=2861 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=COMPACT;

-- ----------------------------
-- Records of task_details
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for user
-- ----------------------------
DROP TABLE IF EXISTS `user`;
CREATE TABLE `user` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键,',
  `uuid` varchar(32) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT 'uuid',
  `is_activation` tinyint DEFAULT '0' COMMENT '是否激活账户  0 未激活 1 已激活',
  `account_no` varchar(20) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '交易账号',
  `parent_id` int DEFAULT NULL COMMENT '邀请人ID',
  `invite_code` varchar(20) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '邀请码',
  `flag` varchar(512) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '用户标识',
  `type` tinyint DEFAULT '1' COMMENT '用户类型：1普通用户',
  `wechat_open_id` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '微信openId,',
  `phone` varchar(20) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '手机号,',
  `user_name` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '用户名,',
  `nick_name` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '昵称,',
  `real_name` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '真实姓名,冗余user_identity表',
  `password` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '密码,',
  `salt` varchar(500) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '密码盐',
  `pay_password` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '支付密码,',
  `sex` tinyint DEFAULT '1' COMMENT '性别1男,2女,',
  `avatar_url` varchar(1024) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '头像图片,',
  `email` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '邮箱,',
  `vip_level` int DEFAULT '0' COMMENT '会员等级',
  `last_login_date` datetime DEFAULT NULL COMMENT '最后登录时间,',
  `login_fail_count` int DEFAULT '0' COMMENT '失败登录次数,',
  `sid` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '登录缓存信息',
  `last_login_ip` varchar(20) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '最后登录ip,',
  `del_flag` tinyint DEFAULT '0' COMMENT '0正常,1删除',
  `version` int DEFAULT '0' COMMENT '版本号,',
  `creator` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '创建人',
  `updator` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '更新人',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间,',
  `update_time` datetime DEFAULT NULL COMMENT '修改时间,',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=926 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_bin ROW_FORMAT=COMPACT COMMENT='用户';

-- ----------------------------
-- Records of user
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for user_goods_collection
-- ----------------------------
DROP TABLE IF EXISTS `user_goods_collection`;
CREATE TABLE `user_goods_collection` (
  `id` int NOT NULL AUTO_INCREMENT,
  `uuid` varchar(32) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL,
  `user_id` int DEFAULT NULL COMMENT '用户id',
  `goods_id` int DEFAULT NULL COMMENT '商品id',
  `type` int DEFAULT NULL COMMENT '收藏类型 0普通，1交易商品 ',
  `del_flag` tinyint DEFAULT '0' COMMENT '0正常,1删除',
  `version` int DEFAULT '0',
  `creator` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL,
  `updator` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL,
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=689 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_bin ROW_FORMAT=COMPACT COMMENT='用户商品收藏表';

-- ----------------------------
-- Records of user_goods_collection
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for user_identity
-- ----------------------------
DROP TABLE IF EXISTS `user_identity`;
CREATE TABLE `user_identity` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键',
  `uuid` varchar(32) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL,
  `user_id` int DEFAULT NULL COMMENT '用户id',
  `user_type` tinyint DEFAULT '1' COMMENT '用户类型:1普通用户;3商家;',
  `real_name` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '真实姓名',
  `id_card` varchar(30) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '身份证号',
  `id_card_pic_a` varchar(1024) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '身份证正面照片',
  `id_card_pic_b` varchar(1024) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '身份证背面照片',
  `real_name_state` tinyint DEFAULT '1' COMMENT '1未认证,2审核中,3审核失败,11人工审核通过,12接口审核通过',
  `apply_time` datetime DEFAULT NULL COMMENT '申请时间',
  `review_time` datetime DEFAULT NULL COMMENT '审核时间',
  `remark` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '备注',
  `del_flag` tinyint DEFAULT '0' COMMENT '0正常,1删除',
  `version` int DEFAULT '0' COMMENT '版本号',
  `creator` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '创建人',
  `updator` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '更新人',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=936 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_bin ROW_FORMAT=COMPACT COMMENT='用户实名认证表';

-- ----------------------------
-- Records of user_identity
-- ----------------------------
BEGIN;
COMMIT;

SET FOREIGN_KEY_CHECKS = 1;
